    std::uint64_t aWandererE = 0U; std::uint64_t aWandererF = 0U; std::uint64_t aWandererG = 0U; std::uint64_t aWandererH = 0U;
    std::uint64_t aWandererI = 0U; std::uint64_t aWandererJ = 0U; std::uint64_t aWandererK = 0U;

    aIngress = 0xAE40532756A1A3EFULL;
    aCarry = 0x96883FADE53158B1ULL;
    aWandererA = 0xEA5E17757EF965E6ULL;
    aWandererB = 0xC905EB67F38CFD5EULL;
    aWandererC = 0xC553DDE4C7C4DDB0ULL;
    aWandererD = 0xA3CA913B7B2179BBULL;
    aWandererE = 0xEF4F771049F69D6BULL;
    aWandererF = 0xCEA202933D7F195FULL;
    aWandererG = 0xB0011B3410721B6DULL;
    aWandererH = 0xC51319DA80DCA2D9ULL;
    aWandererI = 0xB050693F30539CA3ULL;
    aWandererJ = 0xE5B3B4E3CF2EE0AFULL;
    aWandererK = 0xAF7B870B978CF082ULL;

    ////////////////////////////////////////////////////////
    //
    // Main twist loops
    //
    TwistExpander_Alkaid_Arx::TWIST_A(PARAMS_TWIST);

    TwistExpander_Alkaid_Arx::TWIST_B(PARAMS_TWIST);

    TwistExpander_Alkaid_Arx::TWIST_C(PARAMS_TWIST);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixUnrollB;

